addEventListener("error",e=>{let b=document.getElementById("eb");if(!b){b=document.createElement("div");b.id="eb";b.style.cssText="position:fixed;left:0;right:0;bottom:0;z-index:99;background:#5a0a14;color:#fff;font:12px monospace;padding:6px 10px";document.body.appendChild(b)}b.textContent="Error: "+e.message+" (line "+(e.lineno||"?")+")"});
const G="Anchor,Olive,Fern,Halo,Cinder,Echo,Sigil,Tidewater,Canopy,Dusk,Cipher,Ember,Laurel,Papyrus,Solaris,Hush,Crown,Saffron,Palindrome,Sandglass,Haven,Ashen,Lunar,Cornucopia,Zero,Void".split(",");
// name, tag, hue, hazard, status (o open, l code, s signal lost, x forbidden), look [oceanTint,amt,landTint,amt,flood,ice,cloud,cloudColor,cityLights,style], point, report, code
// style: 0 normal, 1 grid, 2 glowing land, 3 tidally locked, 4 permanent night, 5 reverse spin
const E=[
["Home Earth","Where the expedition began",210,0,"o",['#000',0,'#000',0,0,0,1,'#fff',1,0],[46,8,"The Meridian Gate lab"],"Voss|This is where the gate stands, in a converted alpine lab. From orbit Home looks ordinary, and that is the point. Every Earth we logged began as this one and split at a single moment, a decision or a chance event that tipped history sideways. Our job is to find each split, document what grew from it, and come back. Open the gate and pick a door."],
["Concord Earth","The world wars never happened",190,1,"o",['#1f6fd0',.15,'#3f8a45',.15,0,0,.7,'#fff',.7,0],[52.5,13.4,"Berlin Science Concord"],"Voss|Here the Weimar Republic held, and the wars that scarred Home never came. Germany is a hub of rail, research and open borders, and Berlin is the seat of a continental science council. Over eleven days we met nobody who had gone hungry and nobody who feared a knock at the door. The strangest thing was how ordinary it felt: people simply had time, and used it to build things."],
["Saurian Earth","Dinosaurs survived the asteroid",120,5,"o",['#0f6a70',.35,'#2f8a2f',.55,0,0,.9,'#fff',0,0],[-3,-60,"Living-wood city"],"Idris|The asteroid missed, and sixty-six million years of feathered evolution followed. The saurians grow their cities from living trees and speak in scent and pitch, so my recorder was useless. It took nine days to learn to say hello, and the reply was a smell I still cannot describe. They tolerated us the way you tolerate a curious insect."],
["Star Colonies","Humanity settled other planets",200,3,"o",['#28507a',.2,'#607080',.2,0,0,.4,'#fff',1.8,0],[28,-80,"Orbital ring launch"],"Voss|A ship leaves the orbital ring every eleven minutes, and the night side of the planet glows like a circuit board. Most people are born off-world, and Earth has become a quiet museum planet. Pinned to the launch board was a radio log reading 4417, with no source and no explanation. Idris copied it down. Something told me to."],
["Brass Earth","Steampunk",30,3,"o",['#7a6a3a',.4,'#8a5a2b',.5,0,0,1,'#b58a4a',.2,0],[53.5,-2.2,"Airship docks"],"Idris|Steam never gave way to oil, so the sky is copper with smog and the horizon is full of airships. Every machine is riveted, repairable and gorgeous. The tea is excellent. The air is not, and we all came back coughing. Their engineers were delighted by the gate and asked whether it could be fitted with a boiler."],
["The Still Meridian","An experiment froze everything",190,9,"s",['#eaf4ff',.9,'#ffffff',.9,0,1,.4,'#fff',0,0],[64,-19,"Our own equipment"],"Voss|LAST LOG. Every clock on this world stopped mid-second, and the ice is perfectly clear, like glass. On the ice sheet we found a gate frame, coils and a console. The serial numbers match ours. Whatever froze this Earth was a team like us, running the same experiment. I do not think we should stay. I do not think we should run the gate again."],
["Arcane Earth","Magic and powers are normal",280,6,"o",['#3a1a7a',.5,'#6b2ab8',.6,0,0,.6,'#d9a0ff',0,2],[27,90,"Spellwork school"],"Mara|Spellcraft is a school subject here and powers are licensed like driving. Chaos is a job title, and there is a whole ministry for it. I sat in on a beginner class and floated a pencil by accident, which the instructor called promising. This was my last clear report before the static."],
["Drowned Earth","Seas rose 200 metres",215,4,"o",['#0a5ad0',.5,'#1c7f6a',.3,.8,0,.9,'#fff',0,0],[0,-30,"Floating raft-city"],"Idris|The ice caps melted completely, and only a few peaks still break the surface. Cities float on lashed rafts, and the old skylines are reefs where divers salvage steel. Trade runs on salvage rights and weather forecasts. We slept on a ship that had been a hotel, and the captain kept apologising for the view. We also met the deep folk, mermaids and fishmen who steer the trade currents and consider surface dwellers noisy neighbours."],
["Verdant Earth","Intelligent forests",140,5,"o",['#0f5a4a',.3,'#0c7a2c',.8,0,0,.9,'#e6ffe6',0,0],[-2,23,"The Council Grove"],"Idris|Trees here think slowly and decide together through their roots. A single question can take a season to answer. Humans live as guests under an old treaty, and we were asked to leave our metal outside. The Council took four days to agree that we could stay, and one more to agree that we could leave."],
["Twilight Earth","Tidally locked",25,5,"o",['#1d4f86',0,'#9a5a2b',0,0,0,.15,'#fff',0,3],[10,90,"The dusk ring"],"Voss|This Earth never turns. The sun side is a sea of fire and the night side is sheeted in white ice, so life crowds into the thin ring of dusk between them. Age here is measured in walks toward the dark, and the elderly choose how far to go. The light never moves, and I found that harder than the heat."],
["Machine Earth","AI took over",170,9,"s",['#20262e',.7,'#4a5563',.7,0,0,.3,'#889',.5,1],[35,105,"Signal source"],"Mara|TRANSMISSION CORRUPTED. The surface is a grid, lit but empty. Nothing ate, nothing slept. it knows about the gate. it knows about the gate. it wants to go where we came from. it k"],
["Eternal Night","The sun dims",265,7,"o",['#0a1230',.5,'#1b2545',.5,0,0,.2,'#446',1.8,4],[35,139,"Lamp market"],"Idris|The sun dimmed within living memory, and light became the currency. The wealthy live in lamp-lit districts, and the poor navigate by touch and sound. At the lamp market a day of light costs a week of wages. Do not carry a torch openly. A stranger offered to buy ours for a house."],
["Roman Earth","Rome never fell",10,4,"o",['#2a5f9a',.2,'#a8552b',.4,0,0,.8,'#fff',.8,0],[41.9,12.5,"The Forum Network"],"Voss|Rome never fell, and two thousand years of engineering followed. Roads and aqueducts span continents, and the Senate counts ballots by machine, then argues about the result for weeks. Latin is a living language of science. Everyone we met was polite, and everyone was somehow related to a senator."],
["Alexandria Earth","The Library survived",50,2,"o",['#1b7f86',.3,'#c2a04a',.45,0,0,.7,'#fff',1,0],[31.2,29.9,"The Great Library"],"Idris|The Library was never burned, and science began a thousand years early. They already garden on other moons, and their medicine is startling. I was allowed to read one scroll, catalogued as number 2891. It describes a reversed world and warns travelers to bring the code. I asked what code. The librarian said we would know."],
["Sun Empire","The Americas were never colonized",40,3,"o",['#1c6fa0',.2,'#c9a13a',.45,0,0,.7,'#fff',.2,0],[-13.5,-72,"Terraced solar temple"],"Voss|Solar-temple cities cover terraced continents, and gold is decoration, not money. Their astronomers predicted our arrival to the day, which unsettled the whole crew. Trade is by knotted cord and long memory, and every city is aligned to a solstice. They gave us maize bread and a gentle warning about thinking we were the first travelers."],
["Silent Earth","Humans never developed speech",300,6,"s",['#2c2a45',.6,'#4a4566',.6,0,.1,.4,'#a9a0d0',0,0],[-25,133,"Unspeaking city"],"Idris|No word has ever been spoken here. It is not sign language. I still cannot name what they do. It felt like understanding arriving in my head before I could ask the question. I was there four days. When I came back I could not speak for an hour."],
["Britannia Eternal","The United Kingdom never fell",0,4,"o",['#1c4f9e',.1,'#a03a3a',.3,0,0,1,'#fff',1,0],[51.5,-0.1,"Parliament war room"],"Voss|The empire held. The map is a fifth larger and is run from a tea-stained war room under Parliament. The sun does set. Nobody here will admit it, and the maps are drawn very carefully to avoid the subject. They were courteous, deeply organised, and rather sure we were spies."],
["Mughal Ascendant","The Mughal Empire took over",35,3,"o",['#1c6a8a',.2,'#c98a3a',.45,0,0,.6,'#fff',.9,0],[27.2,78,"Garden library"],"Idris|Persian and Sanskrit science merged early, and libraries and gardens span four continents. Astronomy, poetry and engineering are one profession here. Agra is a city of water and marble, and we ate very well. We heard a court concert of sitar and tabla, tasted biryani at a garden banquet, and met an astronomer who called her emperor the finest patron of art in the world. I was gifted a book and asked to promise I would read it slowly."],
["Mirror Earth","Everything runs in reverse",230,7,"l",['#6a8ab0',.5,'#9aa8c0',.5,0,.25,.8,'#fff',.4,5],[40,-100,"Reversed river"],"Voss|Effect comes before cause. Rivers run uphill, people remember tomorrow, and the planet spins the wrong way. I answered a question before it was asked, and a stranger thanked me for something I had not yet done. We left before we had arrived. I still do not understand how.","2891"],
["Hourglass Earth","Time is currency on your wrist",55,6,"o",['#a86f1c',.5,'#d9a441',.55,0,0,.6,'#ffe6a0',.8,0],[40.7,-74,"The wrist exchange"],"Idris|A countdown is tattooed on every wrist. Work earns hours, luxury spends them, and the rich have centuries. The poor haggle over minutes. Breakfast cost us forty minutes, and I did not check the price of the coffee. The gate borrowed a day from all of us and returned it with interest."],
["Paradise Earth","The good one",100,1,"o",['#39c5ff',.45,'#5fe07a',.6,0,0,.5,'#fff',.4,0],[-34,18.4,"The Open Table"],"Voss|No war, no hunger, no lies. Meals are shared at long open tables in every city, and nobody locks a door. It is beautiful, and we could not stay. Idris asked a woman what they did when someone was cruel, and she looked confused, then said they had not needed the word in a very long time."],
["Dominion Earth","The evil one",350,10,"l",['#3a0d12',.75,'#7a1a12',.7,0,0,.7,'#5a2020',.5,2],[55.7,37.6,"The Throne Spire"],"Mara|A tyrant world ruled by fear, with a single tower in every city and a single face on every wall. This gate was opened once by a previous expedition, and something came through. We are not the first team to have come here, and we may not be the last.","4417"],
["Two Moons Earth","A second moon",245,3,"o",['#1c4f9e',.1,'#5a8a6a',.3,0,.05,.8,'#fff',.6,0],[-1,36,"Tidal festival"],"Idris|A second moon doubles the tides, and festivals track the two moons across the year. Harbours rise and fall twice a day like breathing. Lovers argue over which moon is theirs, and the argument is a tradition. It was the gentlest place we visited, and the only one where I slept well."],
["Plenty Earth","No scarcity",80,2,"o",['#2a8ad8',.3,'#4fb35a',.5,0,0,.7,'#fff',1,0],[37,-122,"The Idle Quarter"],"Voss|Nobody works, and nobody is sure why they get up. Machines make everything, and people are left to find a reason. The most dangerous thing on this Earth was boredom, and the second was the poetry that came from it. We were offered jobs, jokingly. I think some were serious."],
["Earth Zero","The origin",0,10,"x",['#200404',.85,'#3a0a04',.8,0,0,.5,'#300',0,2],[-10,20,"The Wound"],"Mara|If you are reading this, the override worked, and I am sorry. This is the first Earth, the one every other world split from, and it has been dying since before we were born. The sky is a scar that never finishes healing. The ground remembers footsteps, including ones that have not happened yet. Something wears our voices and calls to us from the ridges in the dark. I counted the crew three times. Each time there was one more of us than there should be.",12],
["The Unnamed","Not on the map",280,10,"x",['#000',.97,'#000',.97,0,0,0,'#000',0,0],[0,0,"The Watching Door"],"Unknown|There is no light here, only the rim of a planet that reflects nothing. A door stands on the horizon and it faces you however the globe turns. The recording says it knows your name, and the names of everyone who has ever used the gate. It counts visitors. It has stopped counting up. Close this report.",20]];
